var manageNo = gridObj.cells(id, gridObj.getColIndexById("MANAGE_NUMBER")).getValue();
let companyCode = gridObj.cells(id, gridObj.getColIndexById("COMPANY_CODE")).getValue();

callFunction('SLM_122', 'setModeSeal', [manageNo, companyCode]);
callFunction('SLM_122', 'changeHeaderText', ['a', Sepoa.cache.text.get('SLM_121.BTN_DETAIL')]);
callFunction(['p', 'p'], 'changeCell', ['SLM_122']);


var selectedRows = gridObj.getSelectedRows('SELECTED');
var rowCount = gridObj.getSelectedRows('SELECTED').length;

if (rowCount == 0) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004')); //선택된 데이터가 없습니다.
    return;
}

var statusArr = [];
for (var i = 0; i < selectedRows.length; i++) {
    statusArr.push(gridObj._getRowData(selectedRows[i]).SEAL_STATUS);
}

var stausFlag = statusArr.every(function(status) {
    return status == 'C';
});

if (!stausFlag) {
    Alert(Sepoa.cache.text.get('SLM_121.MESSAGE001'));
    return;
}

Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
    if (result) {
        gridObj.editStop();
        gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.seal.SepoaSealManagementService', 'METHOD=doSealFlagUpdateService'], 'SELECTED');
    }
});


let coverProgress = false; // 더블클릭 방지용 프로그레스 모달을 켰는지

var subjectColumn = gridObj.getColIndexById("SUBJECT");
var electronFlag = gridObj.getColIndexById("ELECTRON_FLAG");
var realFlag = gridObj.getColIndexById("REAL_FLAG");
var externalFlag = gridObj.getColIndexById("EXTERNAL_FLAG");
var attachImg = gridObj.getColIndexById("ATTACH_IMG");
var mngNo = gridObj.cells(id, gridObj.getColIndexById("MANAGE_NUMBER")).getValue();
var status = gridObj.cells(id, gridObj.getColIndexById("SEAL_STATUS")).getValue();

var selectedColumn = gridObj.getColIndexById('SELECTED');
var isChecked = gridObj.cells(id, selectedColumn).isChecked();
let selectedCompanyCode = gridObj.cells(id, gridObj.getColIndexById("COMPANY_CODE")).getValue();

if (ind == subjectColumn) {
    sUtils.progress.on();
    coverProgress = true;
    doDetail(id);
} else if (ind == attachImg && status == 'C') {
    doOpenAuditTrailPopup(mngNo, selectedCompanyCode);
}
if (coverProgress) {
    setTimeout(function() {
        sUtils.progress.off();
    }, 100);
}


var process_id;

process_id = "sepoa.svc.seal.SepoaReqSealService"

if (sUtils.workflow.check('MA1693206115042')) { // 인감등록증명서, 날인이력보고서를 pdf가 아닌 파일로 다운로드
    var config = {
        url: window.CONTEXT_NAME + '/SepoaActionController.sux',
        on: {
            callback: function(res, config, params) {
                if (res.flag) {

                } else {
                    console.log(arguments);
                    Alert(Sepoa.cache.text.get('POA_CONTRACT.STATUS_' + res.status));
                }
            }
        }
    }

    var downloadParam = {
        module: process_id,
        action: "doLoadPdf",
        CONNECTION: "CONNECTION",
        PROCESS_ID: process_id,
        MANAGE_NUMBER: mngNo,
        TYPE: "SEALREGIST"
    }

    sUtils.multipart.download(config, downloadParam);
} else {
	let parameters = {
            MANAGE_NUMBER: mngNo,
            PROCESS_ID: process_id,
            METHOD: "doLoadPdf",
            TYPE: "SEALREGIST"
    }
    if (masterAdminFlag == true){
		parameters.COMPANY_CODE = selectedCompanyCode;
	}
    const height = (SUX.getModuleTop().innerHeight - 40) * 0.95;
    sUtils.popup.modal({
        url: window.CONTEXT_NAME + '/UxDefault/Common/PDFViewer.sux',
        params: parameters,
        height: height,
        title: Sepoa.cache.text.get('AUDIT_TRAIL_POPUP.TITLE_MNG')
    });
}

return;


var header = gridObj.getColumnId(cInd);
var sealType = gridObj.cells(rId, gridObj.getColIndexById("SEAL_TYPE")).getValue();
var sealStatus = gridObj.cells(rId, gridObj.getColIndexById("SEAL_STATUS")).getValue();

if (header == 'ELECTRON_FLAG' || header == 'REAL_FLAG' || header == 'EXTERNAL_FLAG') {
    if (sealStatus != "C") {
        return false;
    }
    if (sealType == "C" && header == 'EXTERNAL_FLAG') {
        return false;
    }
    if (sealType == "E" && header == 'EXTERNAL_FLAG') {
        return false;
    }
}

if (stage == 0) {
    return true;
}
return false;


if (count == 0) {
    Alert(Sepoa.cache.text.get('MESSAGE.1001'));
    return;
}

const attachIconColIdx = gridObj.getColIndexById('ATTACH_IMG');
const status = gridObj.getColIndexById('SEAL_STATUS');

gridObj.forEachRow(function(rId) {
    if (gridObj.cells(rId, status).getValue() == 'C') {
        gridObj.cells(rId, attachIconColIdx).cell.children[0].style = 'filter:none';
    }
});


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
if (status == "true") {
    Alert(Sepoa.cache.text.get('MESSAGE.0001'));
    doQuery();
} else {
    Alert(message);
}
